import * as React from "react";
import { cn } from "cn";

import styles from "./cover.module.css";

const dots = Array.from({ length: 32 }, (_, index) => ({
  x: 648 + (index % 8) * 16,
  y: 136 + Math.floor(index / 8) * 16
}));

export type CoverProps = Omit<React.ComponentPropsWithoutRef<"div">, "title"> & {
  title: React.ReactNode;
  tagline?: React.ReactNode;
};

export const Cover = React.forwardRef<HTMLDivElement, CoverProps>(
  ({ title, tagline, className, ...props }, ref) => (
    <div ref={ref} data-slot="cover" className={cn(styles.cover, className)} {...props}>
      <svg className={styles.art} viewBox="480 0 480 288" aria-hidden="true" focusable="false">
        <rect className={cn(styles.slab, styles.block)} x="624" y="-8" width="344" height="216" />
        <rect className={cn(styles.accent, styles.block)} x="512" y="168" width="96" height="96" />
        <rect className={cn(styles.band, styles.block)} x="624" y="224" width="344" height="40" />
        {dots.map((dot) => (
          <rect
            key={`${dot.x}-${dot.y}`}
            className={styles.dot}
            x={dot.x}
            y={dot.y}
            width="4"
            height="4"
          />
        ))}
      </svg>
      <div className={styles.words}>
        <h1 className={styles.title}>{title}</h1>
        {tagline && <p className={styles.tagline}>{tagline}</p>}
      </div>
    </div>
  )
);
Cover.displayName = "Cover";

.cover {
  container-type: inline-size;
  position: relative;
  width: 100%;
  aspect-ratio: 960 / 288;
  overflow: hidden;
  background: var(--v4-surface);
  color: var(--v4-ink);
}
.art {
  position: absolute;
  top: 0;
  right: 0;
  width: 50%;
  height: 100%;
}
.slab {
  fill: var(--v4-ink);
}
.accent {
  fill: var(--v4-accent);
}
.band {
  fill: var(--v4-control);
}
.block {
  rx: calc(var(--v4-radius-card) * var(--corners));
}
.dot {
  fill: var(--v4-on-ink);
  rx: calc(var(--v4-radius-xs) * var(--corners));
}
.words {
  position: absolute;
  bottom: 3.33cqi;
  left: 4.17cqi;
  max-width: 46cqi;
}
.title {
  margin: 0;
  font-family: var(--v4-type-display-font-family);
  font-size: max(var(--v4-type-display-font-size), 10.8cqi);
  line-height: 1;
  font-weight: var(--v4-type-display-font-weight);
  letter-spacing: var(--v4-type-display-letter-spacing);
}
.tagline {
  margin: 1.25cqi 0 0 2px;
  color: var(--v4-muted);
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
}
